export function SpringAnimation({
  bounce = "{{bounce}}",
  duration = {{duration}},
  loop = {{loop}},
  accent = "{{accent}}",
}) {
  const curves = { gentle: ["mot-spr-gentle", "cubic-bezier(.25,1.1,.4,1)"], bouncy: ["mot-spr-bouncy", "cubic-bezier(.34,1.56,.64,1)"], wobbly: ["mot-spr-wobbly", "cubic-bezier(.68,-0.6,.32,1.6)"] };
  const [name, ease] = curves[bounce];
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ position: "relative", height: 26 }}>
        <span className={loop ? "dot loop" : "dot"} style={{ position: "absolute", top: 0, left: 1, width: 22, height: 22, borderRadius: 999, background: accent }} />
      </div>
      <p style={{ margin: "10px 0 0", textTransform: "capitalize" }}>{bounce} spring &middot; overshoots then settles, unlike a plain ease</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .dot { animation: ${name} ${duration}ms ${ease} 1 both; }
          .dot.loop { animation-iteration-count: infinite; }
          @keyframes mot-spr-gentle { from { left: 1px; } to { left: 260px; } }
          @keyframes mot-spr-bouncy { from { left: 1px; } to { left: 260px; } }
          @keyframes mot-spr-wobbly { from { left: 1px; } to { left: 260px; } }
        }
      `}</style>
    </div>
  );
}
